type StringLeafPaths<T, Prefix extends string = ''> = {
  [K in keyof T & string]: T[K] extends string
    ? `${Prefix}${K}`
    : T[K] extends TranslationNode
      ? StringLeafPaths<T[K], `${Prefix}${K}.`>
      : never
}[keyof T & string]

/** All translation keys known at build time. Prefer this type in new UI code. */
export type TranslationKey = StringLeafPaths<typeof messages['en-US']>

const SOURCE_KEY_MAP: Record<string, string> = {
  deepseek_harness_session: 'tools.deepseek_harness',
  'local-files': 'source.localFiles',
  'no-data': 'source.noData',
  simulated: 'source.simulated',
  unknown: 'source.unknown',
  __unknown__: 'sources.unknown',
  __official_api__: 'sources.officialAnthropic'
}

function getByPath(obj: TranslationNode, path: string): string | TranslationNode | undefined {
  return path.split('.').reduce<string | TranslationNode | undefined>((acc, part) => {
    if (!acc || typeof acc === 'string') {
      return undefined
    }
    return acc[part]
  }, obj)
}

function interpolate(template: string, params?: Record<string, string | number>): string {
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (_, key) => String(params[key] ?? `{${key}}`))
}

export function normalizeLocale(locale: string | undefined): AppLocale {
  if (locale === 'en-US') return 'en-US'
  if (locale === 'zh-TW') return 'zh-TW'
  return 'zh-CN'
}

export function t(locale: string | undefined, key: TranslationKey, params?: Record<string, string | number>): string
export function t(locale: string | undefined, key: string, params?: Record<string, string | number>): string
export function t(locale: string | undefined, key: string, params?: Record<string, string | number>): string {
  const resolvedLocale = normalizeLocale(locale)
  const value = getByPath(messages[resolvedLocale], key)
  if (typeof value === 'string') {
    return interpolate(value, params)
  }

  const fallback = getByPath(messages['en-US'], key)
  if (typeof fallback === 'string') {
    return interpolate(fallback, params)
  }

  return key
}

export function sourceLabel(locale: string | undefined, source: string | undefined): string {
  if (source === OFFICIAL_OPENAI_OAUTH_SOURCE_ID) return t(locale, 'sources.openaiOfficial')
  if (source === OFFICIAL_GOOGLE_GEMINI_OAUTH_SOURCE_ID) return t(locale, 'sources.googleOfficial')
  if (source === OFFICIAL_ANTHROPIC_CLAUDE_OAUTH_SOURCE_ID) return t(locale, 'sources.anthropicOfficial')
  const planType = source?.startsWith(OPENAI_OAUTH_PLAN_LABEL_PREFIX)
    ? source.slice(OPENAI_OAUTH_PLAN_LABEL_PREFIX.length)
    : ''
  const planKey: Record<string, string> = {
    free: 'sources.openaiOauthPlanFree',
    go: 'sources.openaiOauthPlanGo',
    plus: 'sources.openaiOauthPlanPlus',
    pro: 'sources.openaiOauthPlanPro',
    business: 'sources.openaiOauthPlanBusiness',
    enterprise: 'sources.openaiOauthPlanEnterprise',
    edu: 'sources.openaiOauthPlanEdu'
  }
  if (planType) return t(locale, planKey[planType] ?? 'sources.openaiOfficial')
  const geminiPlanType = source?.startsWith(GEMINI_OAUTH_PLAN_LABEL_PREFIX)
    ? source.slice(GEMINI_OAUTH_PLAN_LABEL_PREFIX.length)
    : ''
  const geminiPlanKey: Record<string, string> = {
    free: 'sources.geminiOauthPlanFree',
    legacy: 'sources.geminiOauthPlanLegacy',
    standard: 'sources.geminiOauthPlanStandard',
    pro: 'sources.geminiOauthPlanPro',
    ultra: 'sources.geminiOauthPlanUltra',
    enterprise: 'sources.geminiOauthPlanEnterprise'
  }
  if (geminiPlanType) return t(locale, geminiPlanKey[geminiPlanType] ?? 'sources.googleOfficial')
  const key = SOURCE_KEY_MAP[source ?? 'unknown']
  return key ? t(locale, key) : (source?.trim() || t(locale, 'source.unknown'))
}


const NOTE_KEY_MAP: Record<string, string> = {
  NOTE_SIMULATED_DATA: 'backendNote.simulatedData',
  NOTE_NO_REAL_DATA: 'backendNote.noRealData',
  NOTE_PARTIAL_PROXY_COVERAGE: 'backendNote.partialProxyCoverage'
}

const ERROR_KEY_MAP: Record<string, string> = {
  ERR_INVOKE_FAILED: 'backendError.invokeFailed',
  ERR_READ_SETTINGS: 'backendError.readSettings',
  ERR_PARSE_SETTINGS: 'backendError.parseSettings',
  ERR_CREATE_SETTINGS_DIR: 'backendError.createSettingsDir',
  ERR_SERIALIZE_SETTINGS: 'backendError.serializeSettings',
  ERR_WRITE_SETTINGS: 'backendError.writeSettings',
  ERR_SNAPSHOT_TASK_FAILED: 'backendError.snapshotTaskFailed',
  ERR_LOCAL_JSONL_NOT_FOUND: 'backendError.localJsonlNotFound',
  ERR_STATISTICS_TIMEOUT: 'backendError.statisticsTimeout',
  ERR_CONFIGURED_SOURCE_QUOTA_FAILED: 'backendError.configuredSourceQuotaFailed'
}

function parseCodeAndDetail(raw: string): { code: string; detail: string } {
  const idx = raw.indexOf(':')
  if (idx < 0) return { code: raw.trim(), detail: '' }
  return {
    code: raw.slice(0, idx).trim(),
    detail: raw.slice(idx + 1).trim()
  }
}

export function backendNoteLabel(locale: string | undefined, rawNote: string | null | undefined): string {
  if (!rawNote) return ''
  const { code, detail } = parseCodeAndDetail(rawNote)
  const key = NOTE_KEY_MAP[code]
  if (!key) return rawNote
  const base = t(locale, key)
  return detail ? `${base} (${detail})` : base
}

export function backendErrorLabel(locale: string | undefined, rawError: string | null | undefined): string {
  if (!rawError) return ''
  const { code, detail } = parseCodeAndDetail(rawError)
  const key = ERROR_KEY_MAP[code] ?? 'backendError.unknown'
  const base = t(locale, key)
  return detail ? `${base}: ${detail}` : base
}

/// 获取时间窗口名称的国际化显示（使用 settings.window* 键）
export function windowNameLabel(locale: string | undefined, window: string): string {
  const keyMap: Record<string, string> = {
    '5h': 'settings.window5h',
    '24h': 'settings.window24h',
    today: 'settings.windowToday',
    '7d': 'settings.window7d',
    '30d': 'settings.window30d',
    current_month: 'settings.windowCurrentMonth',
    '1m': 'settings.window1m'
  }
  const key = keyMap[window]
  if (key) {
    return t(locale, key)
  }
  return window
}
